cd /home/daniel/ui-work/runs/202610271-as/sandbox/officehq-angular-spring; python3 - <<'EOF'
p='src/main/java/net/officefloor/hq/app/AuditController.java'
s=open(p).read()
s=s.replace('''import java.util.List;
''','''import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
''')
s=s.replace('''    private final Audit audit;

    public AuditController(Audit audit) {
        this.audit = audit;
    }

    /** The sheet's audit lines, newest first; with a name, only those about that person. */''','''    private final Audit audit;
    private final PersonRepository people;

    public AuditController(Audit audit, PersonRepository people) {
        this.audit = audit;
        this.people = people;
    }

    /**
     * The sheet's audit lines, newest first; with a name, only those about that person, followed, when that person was
     * transferred here, by the lines about them from the sheet they came from, newest first.
     */''')
s=s.replace('''        return audit.lines(sheetId.trim(), name);''','''        String sheet = sheetId.trim();
        List<String> lines = new ArrayList<>(audit.lines(sheet, name));
        if (!name.isBlank()) {
            people.findBySheetIdAndNameKey(sheet, Person.key(name))
                    .map(Person::getOriginSheet)
                    .ifPresent(origin -> lines.addAll(audit.lines(origin, name)));
        }
        return lines;''')
open(p,'w').write(s)
EOF
